css.value:
* { 
    font-family: Source Sans Pro;
    font-weight: 600;
    font-size: 24px;
}

script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const {startDate, endDate} = event.payload;
	return {
		params: {
			startDate,
			endDate
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const { startDate, endDate } = api.context.props;
	return {
		route: 'funnels',
		fields: null,
		params: {
			timestamp: Date.now(),
			startDate,
			endDate
		},
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null
	};
}

css.value:
* {
    font-family: Source Sans Pro;
font-style: normal;
